Subroutine Suspendable Revisar(nombre As String, stock As Integer) As String
  If stock = 0 Then
    Return nombre + " no tiene stock";
  EndIf
  Return "";
EndSubroutine

Algorithm Pedido
  Define norte As Integer;
  Define sur As Integer;
  Define oeste As Integer;
  Read norte;
  Read sur;
  Read oeste;
  Tasks
    Define deNorte As Task<String> <- Spawn Revisar("Norte", norte);
    Define deSur As Task<String> <- Spawn Revisar("Sur", sur);
    Define deOeste As Task<String> <- Spawn Revisar("Oeste", oeste);
    Define motivo As String <- Await deNorte + Await deSur + Await deOeste;
    If motivo = "" Then
      Write "Pedido confirmado: ", norte + sur + oeste;
    Else
      Write "Pedido suspendido: ", motivo;
    EndIf
  EndTasks
EndAlgorithm

